/* Anti-inflation: rank needs both quality AND sustained attendance/assessments.
   Rank drops immediately if grade quality falls; growth is capped by history. */
function rankEvidence(student){
 const records=Object.entries(data.marks[student.id]||{})
   .filter(([d])=>d>=startDay&&d<=localDay());
 const active=records.filter(([,slots])=>Array.isArray(slots)&&slots.some(v=>v!==null&&v!==''&&v!==undefined));
 const assessments=active.reduce((n,[,slots])=>n+slots.filter(v=>v!==null&&v!==''&&v!==undefined).length,0);
 const absences=active.reduce((n,[,slots])=>n+slots.filter(v=>v==='Y').length,0);
 return {days:active.length,assessments,absences};
}
function militaryIndex(student){
 if(!student)return -1;
 const v=score(student);
 if(v==null)return -1;
 const quality=Math.min(9,Math.max(0,Math.floor((v-1)/4*10)));
 const ev=rankEvidence(student);
 const targetDays=Math.max(1,Number(extra?.rankDays)||10);
 const targetMarks=Math.max(1,Number(extra?.rankMarks)||17);
 // Podpolkovnik is index 7: sustained high grades over 12 active days,
 // and 20 assessments (out of up to 24 slots). No instant promotions.
 const experience=Math.min(9,Math.floor(ev.days*7/targetDays),Math.floor(ev.assessments*7/targetMarks));
 return Math.min(quality,experience);
}
