const SEC='yhq-security-v1';let security={};try{security=JSON.parse(localStorage.getItem(SEC)||'{}')}catch(e){}let unlocked=!security.secret;let selected=[];const bytes=n=>crypto.getRandomValues(new Uint8Array(n));const hex=b=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');const unhex=s=>Uint8Array.from(s.match(/../g)||[],x=>parseInt(x,16));
