function settingsHTML(){return `<div class="panel"><h3>Kirish xavfsizligi</h3><p>Holat: ${security.secret?'Qulf yoqilgan':'Qulf o‘chiq'}</p><p class="muted">Parol yoki 9 nuqtali chizma tanlang. Chizma nuqtalarni ketma-ket bosish orqali kiritiladi.</p><div class="tools"><select id="method"><option value="password">Parol</option><option value="pattern">Chizma</option></select></div><div id="setupFields"></div><div class="tools"><button class="primary" id="setLock">Saqlash</button>${security.secret?'<button id="lockNow">Qulflash</button><button id="removeLock">Qulfni o‘chirish</button>':''}</div><p id="secMsg" role="status"></p></div><div class="panel"><h3>Barmoq izi / qurilma biometrik himoyasi</h3><p>${security.credential?'Qurilma kaliti ro‘yxatdan o‘tgan.':'Hali ulanmagan.'}</p><p class="muted">WebAuthn orqali qurilma tasdiqlashi: barmoq izi, yuz yoki qurilma PIN kodi. HTTPS yoki localhost va mos brauzer talab qilinadi. Oddiy HTML faylda ishlamasligi mumkin.</p><button id="bioAdd" ${security.secret?'':'disabled'}>Biometrik kirishni ulash</button> ${security.credential?'<button id="bioRemove">Uzish</button>':''}<p id="bioMsg" role="status"></p></div><div class="panel muted">Bu mahalliy interfeys qulfi; jurnal ma’lumotlari shifrlanmaydi. Brauzer xotirasiga yoki dastur kodiga kirish huquqi bor shaxs qulfni chetlab o‘tishi mumkin.</div>`}
function bindSettings(){function fields(){$('setupFields').innerHTML=$('method').value==='pattern'?grid():'<input id="newSecret" type="password" placeholder="Kamida 6 belgili parol" autocomplete="new-password">';if($('clearDots'))dots()}fields();$('method').onchange=fields;$('setLock').onclick=async()=>{try{let method=$('method').value,v=method==='pattern'?selected.join(''):$('newSecret').value;if(v.length<(method==='pattern'?4:6))throw Error('Kamida 4 nuqta yoki 6 belgi kiriting.');if(!confirm(method==='pattern'?'Tanlangan chizma saqlansinmi?':'Yangi parol saqlansinmi?'))return;let salt=hex(bytes(16));persistSec({...security,method,salt,secret:await digest(v,salt)});render()}catch(e){$('secMsg').textContent=e.message}};if($('lockNow'))$('lockNow').onclick=lock;if($('removeLock'))$('removeLock').onclick=()=>{if(confirm('Kirish qulfi o‘chirilsinmi?')){persistSec({});render()}};$('bioAdd').onclick=async()=>{try{if(!window.PublicKeyCredential||!navigator.credentials||!window.isSecureContext||location.protocol==='file:')throw Error('Biometrika uchun saytni HTTPS yoki localhost orqali oching.');let c=await navigator.credentials.create({publicKey:{challenge:bytes(32),rp:{name:'YHQ Academy'},user:{id:bytes(16),name:'yhq-admin',displayName:'YHQ Administrator'},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required'},timeout:60000,attestation:'none'}});if(!c)throw Error('Tasdiqlash bekor qilindi.');persistSec({...security,credential:hex(c.rawId)});render()}catch(e){$('bioMsg').textContent=e.message}};if($('bioRemove'))$('bioRemove').onclick=()=>{let next={...security};delete next.credential;persistSec(next);render()}}
function lock(){unlocked=false;document.querySelector('aside').hidden=true;document.querySelector('main').hidden=true;$('gate').hidden=false;$('gate').innerHTML=`<div class="panel gateCard"><h1>◈ YHQ ACADEMY</h1><h3>Kirish qulfi</h3><p>${security.method==='pattern'?'Chizmani kiriting':'Parolni kiriting'}</p><form id="unlockForm">${security.method==='pattern'?grid():'<input type="password" id="unlockSecret" autocomplete="current-password" required placeholder="Parol">'}<div class="tools"><button class="primary">Kirish</button>${security.credential?'<button type="button" id="bioUnlock">Barmoq izi / biometrika</button>':''}</div></form><p id="gateMsg" role="status"></p></div>`;if($('clearDots'))dots();$('unlockForm').onsubmit=async e=>{e.preventDefault();try{let v=security.method==='pattern'?selected.join(''):$('unlockSecret').value;if(await digest(v,security.salt)===security.secret)openGate();else $('gateMsg').textContent='Parol yoki chizma noto‘g‘ri.'}catch(e){$('gateMsg').textContent=e.message}};if($('bioUnlock'))$('bioUnlock').onclick=async()=>{try{let c=await navigator.credentials.get({publicKey:{challenge:bytes(32),allowCredentials:[{type:'public-key',id:unhex(security.credential)}],userVerification:'required',timeout:60000}});if(c&&hex(c.rawId)===security.credential&&(new Uint8Array(c.response.authenticatorData)[32]&4))openGate();else throw Error('Tasdiqlanmadi.')}catch(e){$('gateMsg').textContent='Biometrik kirish amalga oshmadi. Parol yoki chizmadan foydalaning.'}}}
