function validColor(c){return /^#[0-9a-f]{6}$/i.test(c||'')}function ink(c){let v=c.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*v[0]+.7152*v[1]+.0722*v[2]>.179?'#171717':'#ffffff'}
