/* V13: trusted-device management preview (browser-local only) */
const TRUST_KEY='yhq-trusted-devices-v13';
const THIS_DEVICE_KEY='yhq-this-device-v13';
let trusted=[];
try{trusted=JSON.parse(localStorage.getItem(TRUST_KEY)||'[]');if(!Array.isArray(trusted))trusted=[]}catch(e){trusted=[]}
let thisDevice=localStorage.getItem(THIS_DEVICE_KEY);
if(!thisDevice){thisDevice=hex(bytes(16));localStorage.setItem(THIS_DEVICE_KEY,thisDevice)}
