 v12Render();
 if(tab!==5)return;
 const panel=document.createElement('div');panel.className='panel';
 panel.innerHTML=`<h3>🔐 Ishonchli qurilmalar</h3>
 <p>Ruxsat etilgan qurilmalar: <b>${trusted.length} / 2</b></p>
 <p class="muted">Bu HTML namunasida ro‘yxat faqat shu brauzerda saqlanadi. Boshqa telefondagi qurilmani haqiqiy tekshirish va 2 qurilmadan ortiq kirishni server orqali bloklash uchun backend talab etiladi.</p>
 <div class="tools"><input id="trustedName" maxlength="50" placeholder="Masalan: Mening telefonim" aria-label="Qurilma nomi"><button id="trustedAdd" class="primary" ${trusted.length>=2||trusted.some(x=>x.id===thisDevice)?'disabled':''}>Joriy qurilmani qo‘shish</button></div>
 <div id="trustedList">${trusted.map((t,i)=>`<div class="item"><span>📱 ${esc(t.name)} ${t.id===thisDevice?'<b>(joriy brauzer)</b>':''}<br><small>${esc(t.date)}</small></span><button data-trust-remove="${i}">O‘chirish</button></div>`).join('')||'<p class="muted">Hali qurilma qo‘shilmagan.</p>'}</div>
 <p id="trustedMsg" role="status"></p>`;
 $('view').appendChild(panel);
 const add=$('trustedAdd');
 if(add)add.onclick=()=>{let name=$('trustedName').value.trim();if(!name){$('trustedMsg').textContent='Qurilma nomini kiriting.';return}if(trusted.length>=2){$('trustedMsg').textContent='Faqat 2 ta qurilmaga ruxsat beriladi.';return}if(trusted.some(x=>x.id===thisDevice)){ $('trustedMsg').textContent='Bu brauzer allaqachon ro‘yxatda.';return}
 trusted.push({id:thisDevice,name,date:new Date().toLocaleDateString('uz-UZ')});trustedSave();render()};
 panel.querySelectorAll('[data-trust-remove]').forEach(b=>b.onclick=()=>{if(!confirm('Qurilmani ro‘yxatdan o‘chirasizmi?'))return;trusted.splice(Number(b.dataset.trustRemove),1);trustedSave();render()});
