const HOME_LAYOUT_KEY='yhq-v24-home-layout';
function homeLayout(){try{return Object.assign({hero:true,stats:true,links:true,motivation:true,hidden:[],motivationTitle:'Kun motivatsiyasi',motivationText:'Bilim. Intizom. Natija.'},JSON.parse(localStorage.getItem(HOME_LAYOUT_KEY)||'{}'))}catch(_){return {hero:true,stats:true,links:true,motivation:true,hidden:[],motivationTitle:'Kun motivatsiyasi',motivationText:'Bilim. Intizom. Natija.'}}}
function openLessonDb(){return new Promise((ok,fail)=>{if(!window.indexedDB)return fail(Error('IndexedDB ishlamayapti'));const q=indexedDB.open('yhq-v24-lesson-attachments',1);q.onupgradeneeded=()=>q.result.createObjectStore('files',{keyPath:'id'}).createIndex('date','date');q.onsuccess=()=>ok(q.result);q.onerror=()=>fail(q.error)})}
async function saveLessonFile(date,file){const db=await openLessonDb();return new Promise((ok,fail)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id:date+'_'+Date.now()+'_'+Math.random().toString(36).slice(2),date,name:file.name,blob:file,size:file.size});tx.oncomplete=()=>{db.close();ok()};tx.onerror=()=>{db.close();fail(tx.error)}})}
async function filesForLesson(date){const db=await openLessonDb();return new Promise((ok,fail)=>{const q=db.transaction('files','readonly').objectStore('files').index('date').getAll(date);q.onsuccess=()=>{db.close();ok(q.result)};q.onerror=()=>{db.close();fail(q.error)}})}
async function removeLessonFile(id){const db=await openLessonDb();return new Promise((ok,fail)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>{db.close();ok()};tx.onerror=()=>{db.close();fail(tx.error)}})}
async function showLessonFiles(){for(const el of document.querySelectorAll('[data-lesson-files]')){try{const fs=await filesForLesson(el.dataset.lessonFiles);if(!el.isConnected)continue;el.innerHTML=fs.length?fs.map(f=>`<div class="lesson-file"><span>📎 ${esc(f.name)} (${(f.size/1048576).toFixed(1)} MB)</span><button data-download-file="${esc(f.id)}">Yuklab olish</button><button data-remove-file="${esc(f.id)}">O‘chirish</button></div>`).join(''):'<small>Fayl yo‘q</small>';el.querySelectorAll('[data-download-file]').forEach(b=>b.onclick=()=>{const f=fs.find(x=>x.id===b.dataset.downloadFile),url=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000)});el.querySelectorAll('[data-remove-file]').forEach(b=>b.onclick=async()=>{if(!confirm('Faylni o‘chirasizmi?'))return;await removeLessonFile(b.dataset.removeFile);showLessonFiles()})}catch(e){el.textContent='Fayllarni ochib bo‘lmadi: '+e.message}}}
