/* V24 banner and journal scale extension */
const V24_BANNER_KEY='yhq-v24-banner-config';
const V24_ZOOM_KEY='yhq-v24-journal-zoom';
let v24SlideIndex=0, v24BannerTick=null, v24BgUrl=null;
function v24DefaultSlides(){const h=homeContent();return [{title:h.title,subtitle:h.subtitle,motivation:homeLayout().motivationText},{title:'Yo‘l qoidalarini bilish — hayotni asrash',subtitle:'Har bir dars — xavfsiz harakat sari qadam.',motivation:'E’tibor va intizom muvaffaqiyatga olib keladi.'}]}
function v24BannerConfig(){try{const v=JSON.parse(localStorage.getItem(V24_BANNER_KEY)||'null');if(v&&Array.isArray(v.slides))return {...v,slides:v.slides.filter(x=>x&&typeof x.title==='string')};}catch(_){}return {slides:v24DefaultSlides(),seconds:7,bg:'road',opacity:55}}
function v24SaveBanner(v){localStorage.setItem(V24_BANNER_KEY,JSON.stringify(v))}
function v24BannerShow(){if(tab!==0)return;const hero=document.querySelector('#view .hero');if(!hero)return;const config=v24BannerConfig(),slides=config.slides;if(!slides.length)return;v24SlideIndex=((v24SlideIndex%slides.length)+slides.length)%slides.length;const item=slides[v24SlideIndex];const h=hero.querySelector('h1'),p=hero.querySelector('p');if(h)h.textContent=item.title;if(p)p.textContent=item.subtitle||'';let indicators=hero.querySelector('.v24-banner-indicators');if(!indicators){indicators=document.createElement('div');indicators.className='v24-banner-indicators';hero.append(indicators)}indicators.replaceChildren();slides.forEach((_,i)=>{const b=document.createElement('button');b.type='button';b.className=i===v24SlideIndex?'active':'';b.setAttribute('aria-label',(i+1)+'-banner');b.onclick=()=>{v24SlideIndex=i;v24BannerShow()};indicators.append(b)});const mot=document.querySelector('#view .v24-motivation-rotation');if(mot){const m=mot.querySelector('p');if(m)m.textContent=item.motivation||''}v24ApplyBg(hero,config)}
async function v24BgDb(){return new Promise((ok,fail)=>{const q=indexedDB.open('yhq-v24-banner-background',1);q.onupgradeneeded=()=>q.result.createObjectStore('images');q.onsuccess=()=>ok(q.result);q.onerror=()=>fail(q.error)})}
async function v24BgPut(file){const db=await v24BgDb();return new Promise((ok,fail)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(file,'custom');tx.oncomplete=()=>{db.close();ok()};tx.onerror=()=>{db.close();fail(tx.error)}})}
async function v24BgGet(){const db=await v24BgDb();return new Promise((ok,fail)=>{const q=db.transaction('images','readonly').objectStore('images').get('custom');q.onsuccess=()=>{db.close();ok(q.result)};q.onerror=()=>{db.close();fail(q.error)}})}
function v24ApplyBg(hero,cfg){hero.classList.add('v24-rotating-banner');hero.style.setProperty('--banner-shade',String(Math.max(.1,Math.min(.85,(+cfg.opacity||55)/100))));hero.style.backgroundImage=cfg.bg==='none'?'linear-gradient(110deg,#11689c,#59b6e3)':`linear-gradient(100deg,rgba(5,40,70,var(--banner-shade)),rgba(5,40,70,.42)),url('./road-banner.svg')`;if(cfg.bg==='custom'){v24BgGet().then(file=>{if(!hero.isConnected||v24BannerConfig().bg!=='custom')return;if(v24BgUrl)URL.revokeObjectURL(v24BgUrl);if(file){v24BgUrl=URL.createObjectURL(file);hero.style.backgroundImage=`linear-gradient(100deg,rgba(5,40,70,var(--banner-shade)),rgba(5,40,70,.42)),url("${v24BgUrl}")`}}).catch(()=>{})}}
function v24StartBanner(){if(v24BannerTick){clearInterval(v24BannerTick);v24BannerTick=null}if(tab!==0)return;v24BannerShow();const c=v24BannerConfig();if(c.slides.length>1)v24BannerTick=setInterval(()=>{if(tab!==0){clearInterval(v24BannerTick);v24BannerTick=null;return}v24SlideIndex=(v24SlideIndex+1)%v24BannerConfig().slides.length;v24BannerShow()},Math.max(3,Math.min(60,+c.seconds||7))*1000)}
function v24ScaleJournal(){if(tab!==1)return;const journal=document.querySelector('#view .journal');if(!journal)return;let scale=Number(localStorage.getItem(V24_ZOOM_KEY)||100);scale=Math.max(60,Math.min(150,scale));const toolbar=document.createElement('div');toolbar.className='v24-zoom-toolbar';toolbar.innerHTML=`<strong>Jurnal masshtabi</strong><button type="button" data-zoom-minus>−</button><input type="range" min="60" max="150" step="5" value="${scale}" aria-label="Jurnal masshtabi"><output>${scale}%</output><button type="button" data-zoom-plus>+</button><button type="button" data-zoom-reset>100%</button>`;const host=journal.closest('.scroll')||journal.parentElement;host.parentElement.insertBefore(toolbar,host);const slider=toolbar.querySelector('input'),output=toolbar.querySelector('output');function set(v){v=Math.max(60,Math.min(150,Math.round(v/5)*5));journal.style.zoom=v+'%';slider.value=v;output.textContent=v+'%';try{localStorage.setItem(V24_ZOOM_KEY,String(v))}catch(_){}}slider.oninput=()=>set(+slider.value);toolbar.querySelector('[data-zoom-minus]').onclick=()=>set(+slider.value-5);toolbar.querySelector('[data-zoom-plus]').onclick=()=>set(+slider.value+5);toolbar.querySelector('[data-zoom-reset]').onclick=()=>set(100);set(scale)}
function v24BannerSettings(){if(tab!==5)return;const config=v24BannerConfig();const panel=document.createElement('div');panel.className='panel v24-banner-settings';panel.innerHTML=`<h3>🚦 Motivatsion bannerlar</h3><p class="muted">Har bir bannerda katta sarlavha, taglavha va motivatsion gap alohida bo‘ladi. Ketma-ket avtomatik almashadi. Tartibini o‘zgartirishingiz mumkin.</p><div id="v24-banner-list"></div><div class="tools"><button type="button" id="v24-add-slide">+ Yangi banner</button></div><label>Almashish oralig‘i (soniya)<input id="v24-slide-seconds" type="number" min="3" max="60" value="${config.seconds||7}"></label><label>Banner fon rasmi<select id="v24-bg-select"><option value="road">Yo‘l harakati rasmi</option><option value="custom">O‘zim yuklagan rasm</option><option value="none">Oddiy moviy fon</option></select></label><label>O‘z rasmingizni yuklang (JPG, PNG, WEBP; 4 MB gacha)<input type="file" id="v24-bg-file" accept="image/png,image/jpeg,image/webp"></label><label>Fon ustidagi qoraytirish darajasi: <output id="v24-shade-out">${config.opacity||55}%</output><input id="v24-shade" type="range" min="20" max="85" value="${config.opacity||55}"></label><button type="button" class="primary" id="v24-save-banner">Bannerlarni saqlash</button>`;document.getElementById('view').append(panel);panel.querySelector('#v24-bg-select').value=config.bg||'road';let working=config.slides.map(x=>({...x}));const list=panel.querySelector('#v24-banner-list');function collect(){[...list.querySelectorAll('.v24-slide-editor')].forEach((row,i)=>{if(working[i]){working[i].title=row.querySelector('[data-field=title]').value;working[i].subtitle=row.querySelector('[data-field=subtitle]').value;working[i].motivation=row.querySelector('[data-field=motivation]').value}})}function draw(){list.replaceChildren();working.forEach((slide,i)=>{const box=document.createElement('div');box.className='v24-slide-editor';box.innerHTML=`<strong>${i+1}-banner</strong><label>Katta sarlavha<input data-field="title" maxlength="140" required></label><label>Taglavha<textarea data-field="subtitle" maxlength="350"></textarea></label><label>Motivatsion gap<textarea data-field="motivation" maxlength="500"></textarea></label><div class="tools"><button type="button" data-move="up">↑ Yuqoriga</button><button type="button" data-move="down">↓ Pastga</button><button type="button" data-move="delete">O‘chirish</button></div>`;box.querySelector('[data-field=title]').value=slide.title||'';box.querySelector('[data-field=subtitle]').value=slide.subtitle||'';box.querySelector('[data-field=motivation]').value=slide.motivation||'';box.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{collect();const action=b.dataset.move;if(action==='delete'){if(working.length===1)return alert('Kamida bitta banner qolsin');working.splice(i,1)}else{const j=i+(action==='up'?-1:1);if(j<0||j>=working.length)return;[working[i],working[j]]=[working[j],working[i]]}draw()});list.append(box)})}draw();panel.querySelector('#v24-add-slide').onclick=()=>{collect();working.push({title:'Yangi motivatsiya',subtitle:'',motivation:''});draw()};panel.querySelector('#v24-shade').oninput=e=>panel.querySelector('#v24-shade-out').textContent=e.target.value+'%';panel.querySelector('#v24-save-banner').onclick=async()=>{collect();if(working.some(x=>!x.title.trim()))return alert('Har bir bannerga sarlavha kiriting');const file=panel.querySelector('#v24-bg-file').files[0];if(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4*1024*1024)return alert('JPG, PNG yoki WEBP rasm 4 MB dan oshmasin');try{await v24BgPut(file)}catch(err){return alert('Fon rasmi saqlanmadi: '+err.message)}}const v={slides:working,seconds:Math.max(3,Math.min(60,+panel.querySelector('#v24-slide-seconds').value||7)),bg:panel.querySelector('#v24-bg-select').value,opacity:+panel.querySelector('#v24-shade').value};try{v24SaveBanner(v);v24SlideIndex=0;alert('Bannerlar saqlandi');render()}catch(err){alert('Saqlanmadi: '+err.message)}}}
const v24PreviousRender=render;
render=function(){v24PreviousRender();if(tab===0){const mot=document.querySelector('#view .panel:last-child');if(mot&&mot.querySelector('h3')?.textContent===homeLayout().motivationTitle)mot.classList.add('v24-motivation-rotation');v24StartBanner()}else{if(v24BannerTick){clearInterval(v24BannerTick);v24BannerTick=null}if(tab===1)v24ScaleJournal();if(tab===5)v24BannerSettings()}};
render();


const oldRenderV24=render;
render=function(){oldRenderV24();if(tab===2){const p=document.createElement('div');p.className='panel';p.innerHTML='<h3>🔐 O‘quvchi ID / login / parol</h3><p class="muted">O‘quvchiga alohida login yarating. Parol faqat yaratilgan paytda ko‘rsatiladi.</p><div id="student-credentials">Yuklanmoqda...</div>';document.getElementById('view').append(p);loadCredentials(p)} };
async function loadCredentials(panel){try{const r=await api('/api/teacher/accounts');const box=panel.querySelector('#student-credentials');if(!box)return;box.innerHTML=r.map(a=>`<div class="item"><span>${esc(a.name)}<small style="display:block">ID: ${esc(a.id)} · Login: ${esc(a.login||'yaratilmagan')}</small></span><span><button data-create-login="${esc(a.id)}">${a.login?'Parolni yangilash':'Login yaratish'}</button> ${a.login?`<button data-toggle-login="${esc(a.id)}">${a.active?'Bloklash':'Faollashtirish'}</button>`:''}</span></div>`).join('');box.querySelectorAll('[data-create-login]').forEach(b=>b.onclick=async()=>{const login=prompt('O‘quvchi uchun login (lotin harflari, raqamlar)', 'student'+b.dataset.createLogin.replace(/[^a-z0-9]/gi,'').slice(-8));if(login===null)return;const pass=prompt('Boshlang‘ich parol (kamida 8 belgi). Uni o‘quvchiga xavfsiz yetkazing:');if(pass===null)return;try{await api('/api/teacher/account','POST',{id:b.dataset.createLogin,login,password:pass});alert('Login yaratildi / parol yangilandi. Parolni o‘quvchiga bering.');loadCredentials(panel)}catch(e){alert(e.message)}});box.querySelectorAll('[data-toggle-login]').forEach(b=>b.onclick=async()=>{try{await api('/api/teacher/account/toggle','POST',{id:b.dataset.toggleLogin});loadCredentials(panel)}catch(e){alert(e.message)}})}catch(e){panel.querySelector('#student-credentials').textContent=e.message}}
async function api(url,method='GET',payload){const r=await fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':document.cookie.match(/(?:^|; )yhq_csrf=([^;]+)/)?.[1]||''},body:payload?JSON.stringify(payload):undefined});if(r.status===401){location.href='/login';throw Error('Qayta kiring')}const x=await r.json();if(!r.ok)throw Error(x.detail||'Server xatosi');return x}
let pendingSave=Promise.resolve();const originalSaveV24=save;
save=function(){originalSaveV24();const snapshot=JSON.parse(JSON.stringify(data));pendingSave=pendingSave.then(()=>api('/api/teacher/state','PUT',snapshot)).catch(e=>{const el=document.getElementById('status');if(el)el.textContent='⚠️ Serverga saqlanmadi: '+e.message;alert('Serverga saqlanmadi: '+e.message)})};
// Backup and student accounts are server-side. Never publish teacher backup JSON to students.
render();

// Lesson files are stored on the server, not only in one browser.
saveLessonFile=async function(day,file){const fd=new FormData();fd.append('file',file);const r=await fetch('/api/teacher/lesson-file/'+encodeURIComponent(day),{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':document.cookie.match(/(?:^|; )yhq_csrf=([^;]+)/)?.[1]||''},body:fd});if(!r.ok){let e=await r.json().catch(()=>({}));throw Error(e.detail||'Fayl saqlanmadi')}};
showLessonFiles=async function(){for(const el of document.querySelectorAll('[data-lesson-files]')){try{const files=await api('/api/lesson-files/'+encodeURIComponent(el.dataset.lessonFiles));if(!el.isConnected)continue;el.innerHTML=files.map(f=>`<div class="lesson-file"><span>📎 ${esc(f.name)} (${(f.size/1048576).toFixed(1)} MB)</span><button data-file-download="${f.id}">Yuklab olish</button><button data-file-delete="${f.id}">O‘chirish</button></div>`).join('')||'<small>Fayl biriktirilmagan</small>';el.querySelectorAll('[data-file-download]').forEach(b=>b.onclick=()=>location.href='/api/lesson-file/'+b.dataset.fileDownload);el.querySelectorAll('[data-file-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Faylni o‘chirasizmi?'))return;await api('/api/teacher/lesson-file/'+b.dataset.fileDelete,'DELETE');showLessonFiles()})}catch(e){el.textContent='Fayl ro‘yxati yuklanmadi: '+e.message}}};

// Migration from the original V24 HTML export. Only teacher can import.
const migration=document.createElement('div');migration.className='panel';migration.innerHTML='<h3>📥 Eski V24 ma’lumotlarini serverga ko‘chirish</h3><p>Eski V24 saytining Zahira bo‘limidan JSON yuklab oling. Uni bu yerda tanlang. Diqqat: serverdagi mavjud jurnalni almashtiradi.</p><input type="file" id="server-v24-import" accept=".json,application/json"><button class="primary" id="server-v24-import-button">JSON ni serverga yuklash</button><p id="server-v24-import-status"></p>';document.getElementById('view').parentElement.appendChild(migration);migration.style.display='none';const oldRenderMigration=render;render=function(){oldRenderMigration();migration.style.display=tab===11?'block':'none'};
document.getElementById('server-v24-import-button').onclick=async()=>{const f=document.getElementById('server-v24-import').files[0];if(!f)return alert('JSON fayl tanlang');if(!confirm('Serverdagi mavjud jurnal almashtiriladi. Davom etasizmi?'))return;try{const obj=JSON.parse(await f.text());if(!Array.isArray(obj.students)||!Array.isArray(obj.groups)||!obj.marks)throw Error('V24 JSON fayli mos emas');await api('/api/teacher/state','PUT',obj);localStorage.setItem('yhq-academy-v1',JSON.stringify(obj));location.reload()}catch(e){document.getElementById('server-v24-import-status').textContent=e.message}};

const exitButton=document.createElement('button');exitButton.textContent='Chiqish';exitButton.style.cssText='position:fixed;top:12px;right:12px;z-index:9999;background:#125b90;color:white;border:0;border-radius:9px;padding:10px';exitButton.onclick=async()=>{await api('/api/logout','POST');location.href='/login'};document.body.appendChild(exitButton);

// Student account updates are reflected in the teacher interface without manual refresh.
let v24AccountRevision=null;
setInterval(async()=>{
 if(document.hidden)return;
 try{
  const rev=await api('/api/teacher/accounts/revision');
  if(v24AccountRevision){
   if(rev.state!==v24AccountRevision.state && tab===2 && !document.activeElement?.matches('input,textarea')){
    // Student IDs may have changed: reload the authoritative server journal.
    await pendingSave;
    const fresh=await api('/api/teacher/state');
    data=fresh;
    localStorage.setItem('yhq-academy-v1',JSON.stringify(fresh));
    render();
   }else if(rev.audit!==v24AccountRevision.audit && tab===2){
    const panel=document.querySelector('#student-credentials')?.closest('.panel');
    if(panel)loadCredentials(panel);
   }
  }
  v24AccountRevision=rev;
 }catch(e){}
},5000);
